package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamLowCountryMasksBank2 {
    private const val T = "පහතරට නර්තන සම්ප්‍රදාය හා වෙස්මුහුණු කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පහතරට වෙස්මුහුණු කැපීමේදී ලී කොටය පළමුව කපා ගැනීමෙන් පසු එය දින කිහිපයක් පදම් කරන්නේ ඇයි?", "තෙතමනය ඉවත් වී පිපිරීම් හා කෘමි හානි වැළැක්වීමට", "දැව කොටයේ බර තවත් වැඩි කර ගැනීමට", "කැටයම් කැපීමට පෙර ලීය මෘදු කර හැරීමට", "ස්වාභාවික වර්ණ තීන්ත පහසුවෙන් සේදීමට", "දුම් මැස්සේ හෝ සෙවණේ වියළීමෙන් වෙස්මුහුණ කල්පැවැත්මෙන් යුක්ත වේ."),
        q("පහතරට කෝලම් නැටුමේ 'පොලිස් කෝලම' හෝ 'මුදලි කෝලම' අයත් වන්නේ කුමන වර්ගයේ මුහුණු කාණ්ඩයටද?", "සමාජීය හා ඓතිහාසික මිනිස් චරිත වෙස්මුහුණු", "සන්නි යක් වෙස්මුහුණු", "සත්ව රක්ෂ වෙස්මුහුණු", "දේව ආභරණ", "පොදු සමාජයේ විවිධ චරිත නිරූපණය සඳහා ස්වාභාවික හා උපහාසාත්මක මුහුණු කපනු ලැබේ."),
        q("පහතරට 'දහඅට සන්නිය' තුළ දක්නට ලැබෙන 'වෙඩි සන්නිය' හෝ 'වැදි සන්නිය' මගින් නිරූපණය කරන්නේ කුමන චරිතයද?", "වනයේ වාසය කරන දඩයක්කාර වැදි රූපයක්", "රාජ සභාවේ ඇමතිවරයෙක්", "නාවික කපිතාන්වරයෙක්", "පාසල් ගුරුවරයෙක්", "දුනු ඊතල අතැතිව හාස්‍යජනක දෙබස් පවසමින් වැදි සන්නිය වේදිකාවට පැමිණේ."),
        q("පහතරට 'රයිගම' ගුරුකුලයේ නැටුම් ශෛලිය ප්‍රචලිත වී ඇති ශ්‍රී ලංකාවේ ප්‍රධාන ප්‍රදේශය කුමක්ද?", "කළුතර හා බස්නාහිර පළාතේ හොරණ, රයිගම අවට", "මාතර හා හම්බන්තොට", "මහනුවර හා මාතලේ", "අම්පාර හා මඩකලපුව", "රයිගම කෝරළය ආශ්‍රිතව බිහි වූ නර්තන ලක්ෂණ රයිගම ගුරුකුලය නම් වේ."),
        q("පහතරට 'බෙන්තර' ගුරුකුලය පිහිටා ඇති ප්‍රධාන දිස්ත්‍රික්ක සීමාව කුමක්ද?", "ගාල්ල හා කළුතර දිස්ත්‍රික් සීමාවේ බෙන්තර ප්‍රදේශය", "කුරුණෑගල දිස්ත්‍රික්කය", "අනුරාධපුර දිස්ත්‍රික්කය", "රත්නපුර දිස්ත්‍රික්කය", "බෙන්තර ගඟ අවට පරම්පරාගතව පැවති සම්ප්‍රදාය බෙන්තර ගුරුකුලයයි."),
        q("පහතරට 'මාතර' ගුරුකුලයට ආවේණික වූ සුවිශේෂී ලක්ෂණයක් ලෙස සැලකෙන්නේ කුමක්ද?", "තෙල්මේ හා යාග නැටුම්වල ජවසම්පන්න බව හා විචිත්‍ර පද රටා", "ගැටබෙරය පමණක් වැයීම", "වන්නම් 18 නැටීම පමණක්", "සොකරි කමතේ නැටීම", "දකුණු ලක මාතර සම්ප්‍රදාය තාල වාදන හා පෙළපාලි අතින් අතිශය පොහොසත්ය."),
        q("පහතරට නැට්ටුවෙකු පළඳින 'කබාය' හෙවත් උඩුකය හැට්ටයේ ප්‍රධාන වර්ණ මොනවාද?", "රතු හෝ සුදු පැහැය මත රන් හෝ රිදී රේන්ද මෝස්තර", "තද අළු පැහැය පමණි", "තනි කොළ පැහැය පමණි", "කළු ඉරි පමණි", "පන්දම් එළියේ දීප්තිමත්ව පෙනෙන සේ රතු හා සුදු වර්ණ භාවිත කෙරේ."),
        q("පහතරට 'කෝලම්' රංගනයේදී වෙස්මුහුණු පැළඳ සිටින නළුවා කතා නොකර අභිනය කරන විට දෙබස් කියවන්නේ කවුද?", "සභාපති හෙවත් කාරියකරවන රාළ සහ බෙර වාදකයා", "වේදිකාවෙන් පිටත සිටින ළමුන්", "වෙස්මුහුණු කපන වඩුවා", "මල් පූජා කරන පිරිස", "වෙස්මුහුණ නිසා කතා කිරීමට අපහසු විට සභාපති විසින් කවි හා අර්ථ කථනය සිදු කරයි."),
        q("පහතරට 'සන්නි' ශාන්තිකර්මයේදී ආතුරයා හෙවත් රෝගියා වාඩි කරවන ආසනය පිහිටුවන්නේ කොතැනකද?", "සන්නි වීදිය හා මල් යහන ඉදිරිපිට ශුද්ධ භූමියේ", "නිවසේ මුළුතැන්ගෙය තුළ", "මහ පාර අයිනේ", "වහලය මත", "ආතුරයාට සම්පූර්ණ රංගනය පෙනෙන සේ යාග මඩුවේ ඉදිරිපස අසුන් ගන්වයි."),
        q("පහතරට නැටුමේදී යොදා ගන්නා 'පඳුරු තාලය' හෝ 'පද පෙළ' ඉදිරිපත් කරන බෙර වර්ගය කුමක්ද?", "පහතරට යක් බෙරය", "උඩරට උඩැක්කිය", "සබරගමු දිගු දවුල", "ඉන්දියානු තබ්ලාව", "දිගැති කඳක් ඇති යක් බෙරයේ දෙපසම ගව හෝ තලගොයි සම් යොදා ඇත."),
        q("පහතරට යක් බෙරයේ බඳ නිමවීම සඳහා බහුලව යොදාගන්නා දැව වර්ග මොනවාද?", "ඇහැල, කොස් හෝ කොහොඹ ලී", "පයිනස් ලී", "රබර් ලී", "ප්ලාස්ටික් නල", "ශබ්ද අනුනාදය හා ශක්තිය ඉහළ නිසා ඇහැල හා කොස් ලී බෙර කඳට සුදුසුය."),
        q("පහතරට නැටුමේදී නැට්ටුවා 'පාද ඉහළට ඔසවා හරස් කර තබන' විශේෂිත පැනුම් පියවර හඳුන්වන්නේ කෙසේද?", "පහතරට අඩි ගැසීම හා පැනුම්", "උඩරට බඹර කැරකිල්ල", "සබරගමු ගමන් පදය", "රබන් කරකැවීම", "පහතරට නැටුමේදී දෙපා පොළොවට ශක්තිමත්ව ගසමින් රිද්මය මතු කරයි."),
        q("කෝලම් නැටුමේ 'පිටවීම්' අතර ජනප්‍රිය 'ආරච්චි කෝලම' මගින් නිරූපණය කරන්නේ කුමක්ද?", "ගමේ ආරච්චි හෙවත් නිලධාරියාගේ ක්‍රියාකලාපය", "වන සතුන්ගේ ජීවිතය", "රෝගීන්ගේ වේදනාව", "සිංහල අවුරුදු ක්‍රීඩා", "අල්ලස් ගැනීම් හා බල පරාක්‍රමය හාස්‍යයෙන් විවේචනය කිරීමට ආරච්චි කෝලම යොදයි."),
        q("පහතරට 'මහ සන්නි' වෙස්මුහුණේ දෙපස කැටයම් කර ඇති කුඩා මුහුණු ගණන කීයද?", "දහඅටකි (18)", "දෙකකි (2)", "හතරකි (4)", "දහයකි (10)", "සියලුම සන්නි යකුන් 18 දෙනා එක් මහා මුහුණක කැටයම් කර තිබීම විශේෂත්වයකි."),
        q("පහතරට 'සන්නි' ශාන්තිකර්මයේදී 'පිස්සු සන්නිය' හෙවත් 'පිත් සන්නිය' පැමිණි විට පෙන්වන රෝග ලක්ෂණ කුමක්ද?", "උන්මත්තක බව හා අක්‍රමවත් කතා බහ", "කන් ඇසීම අඩු වීම", "දණහිස් කොර වීම", "ගොළු වී සිටීම", "මානසික ව්‍යාකූලත්වය හා පිත් දෝෂ නිසා ඇතිවන රෝග ලක්ෂණ මෙහි රඟ දැක්වේ."),
        q("පහතරට 'ගුරුළු' නැටුම ඉදිරිපත් කිරීමේදී නැට්ටුවා අතැතිව හෝ කයෙහි පළඳින විශේෂ අංගය කුමක්ද?", "පියාපත් සැරසිලි හා ගුරුළු රක්ෂ වෙස්මුහුණ", "ගැමි ජන නැටුමේ මැටි කළගෙඩිය", "සොකරි කමතේ ලී මෝල්ගස් යුගලය", "අවුරුදු රබන් ක්‍රීඩාවේ අත් රබාන", "පක්ෂි රාජයෙකු මෙන් අත් විහිදුවා වේගවත් කැරකිලි දැමීම මෙහි විශේෂත්වයකි."),
        q("පහතරට 'තෙල්මේ' නැටුමේදී නැට්ටුවන් අතැතිව නටන හෝ හිසේ පළඳින ආභරණ අතර ඇති විශේෂ උපකරණය කුමක්ද?", "තෙල්මේ තොප්පිය සහ සුදු සළුව", "කඩුව සහ පලිහ", "ලී කෙළි", "වේවැල් කුල්ල", "දෙවියන් පිදීම සඳහා නටන තෙල්මේ නැටුමේදී රතු හිස්වැසුම ප්‍රධාන වේ."),
        q("පහතරට වෙස්මුහුණු කලාවේදී මුහුණේ ඇස් නෙරා ගිය හා දත් දිගු වූ ස්වරූපයක් දෙන්නේ කුමන වර්ගයේ මුහුණුවලටද?", "රකුසු හා සන්නි වෙස්මුහුණුවලට", "රජ බිසව වෙස්මුහුණුවලට", "සාමාන්‍ය ගැමි කාන්තා මුහුණුවලට", "හේවා රාළගේ පවුලේ මුහුණුවලට", "අමනුෂ්‍ය බලවේග හා භයංකර බව පෙන්වීම සඳහා විශාල දත් හා ඇස් යොදයි."),
        q("පහතරට 'කෝලම්' නැටුම් සඳහා පසුබිම් වූ ප්‍රකට පුරාවෘත්තය කුමන රජ බිසවක් හා සම්බන්ධද?", "මහ සම්මත රජුගේ බිසව වූ මැණික්පාල බිසව", "කුවේණි බිසව", "විහාරමහා දේවිය", "සීතා දේවිය", "වෙස්මුහුණු පැළඳ නටන විකට රංගනයක් දැකීමට බිසවට ඇති වූ දොළදුක මෙයට මුල් විය."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'වට්ටම්' නැටුම් කොටස් වලදී භාවිත කරන පද මාලාව හඳුන්වන්නේ කුමන නමකින්ද?", "වට්ටම් පද හෙවත් තෙල්මේ වට්ටම්", "වන්නම් තානම්", "සබරගමු ගමන් තාල", "බටහිර ස්වර", "පහතරට නැටුමේ ජවය හා ශිල්පීය හැකියාව පෙන්වීමට වට්ටම් පද නටනු ලැබේ."),
        q("පහතරට 'දහඅට සන්නිය' ශාන්තිකර්මයේදී යකැදුරා හා බෙර වාදකයා අතර සිදුවන 'සංවාදය' කෙබඳු වේද?", "හාස්‍ය හා සමාජ උපහාසය පිරි ප්‍රශ්නෝත්තර සංවාදයක්", "ප්‍රේක්ෂකයන්ට නොඇසෙන රහස් මන්ත්‍ර කෙඳිරිල්ලක්", "තාලයකින් තොරව කියවන සරල ගද්‍ය විස්තරයක්", "වචන කිසිවක් නොමැති නිහඬ අභිනය රංගනයක්", "ගුරුන්නාන්සේ (බෙරකරු) සන්නි යකාගෙන් පැමිණි කාරණය අසමින් රෝගය හඳුනා ගනී."),
        q("පහතරට නැට්ටුවාගේ ඉණෙහි බඳින 'ඉණ පටිය' හෙවත් රතු පැහැති සළුව ඇඳීමේ ක්‍රමය කුමක්ද?", "ඉණ වටා තදින් ඔතා ඉදිරියෙන් පොටක් එල්ලීම", "හිස වටා ජටාවක් මෙන් කරකවා ගැටගැසීම", "සිළම්බු සමඟ දෙපා වළලුකරේ දවටා බැඳීම", "උරහිස් හරහා කතිර හැඩයට දමා තද කිරීම", "රැළි රෙද්ද ස්ථිරව රඳවා ගැනීමට මෙම ඉණ පටිය උපකාරී වේ."),
        q("පහතරට වෙස්මුහුණු කලාවේදී ලීය මත කැටයම් කපා අවසන් වූ පසු සිනිඳු කිරීම සඳහා භාවිත කළ ස්වාභාවික ශාක පත්‍රය කුමක්ද?", "මොටදැලියා හෝ කොරොස්ස කොළ", "කෙසෙල් කොළ", "නෙළුම් කොළ", "තේ කොළ", "පැරණි කලාකරුවන් වැලි කඩදාසි වෙනුවට ගොරෝසු මතුපිට ඇති කොරොස්ස කොළ භාවිත කළහ."),
        q("පහතරට 'ගම්මඩු' ශාන්තිකර්මය ප්‍රධාන වශයෙන් කැප කරනු ලබන්නේ කුමන දේවතාවිය උදෙසාද?", "පත්තිනි මෑණියන් උදෙසා", "කාලි මෑණියන් උදෙසා පමණි", "සරස්වතී දේවිය උදෙසා", "ලක්ෂ්මී දේවිය උදෙසා", "ගමට සෙත් ශාන්තිය හා වසංගත රෝග දුරු වීම පතා පත්තිනි දේවියට ගම්මඩු පවත්වයි."),
        q("පහතරට 'දෙවොල් මඩුවේදී' දැකිය හැකි ඉතා ත්‍රාසජනක හා භක්තිමත් ප්‍රධාන චාරිත්‍රය කුමක්ද?", "ගිනි මැලය නිවා ගිනි පෑගීම", "දිය යට පිහිනීම", "උණ ගස් නැගීම", "කඹ ඇදීම", "දෙවොල් දෙවියන්ගේ බලයෙන් ගිනි අඟුරු මත පය තබා ඇවිදීම මෙහි විශේෂ අංගයකි."),
        q("පහතරට කෝලම් නාට්‍යයේ 'වැදි කෝලම' රඟ දක්වන විට නළුවා අතේ ගෙන එන ප්‍රධාන උපකරණය කුමක්ද?", "දුන්න හා ඊතල", "පොත හා පෑන", "මැටි කළය", "තාලම්පට", "වැදි රජුගේ දඩයම් ජීවිතය පෙන්වීමට දුනු ඊතල හා කොළ අතු යොදා ගනී."),
        q("පහතරට නර්තන සම්ප්‍රදායේදී 'පහතරට පා සරඹ' සඳහා යොදා ගන්නා මූලික ඉරියව්ව කුමක්ද?", "දෙපා පළල් කර දණහිස් දෙපසට නැමූ පහතරට මණ්ඩිය", "සීරුවෙන් සිටින ඉරියව්ව", "එක් කකුලකින් සිටින ඉරියව්ව", "බිම දණ ගසා සිටින ඉරියව්ව", "ශක්තිමත් පදනමක් ලබා දීමට පහතරට මණ්ඩිය පුහුණු කෙරේ."),
        q("පහතරට නැටුමේදී 'තාලම්පට' නොමැතිව බොහෝ විට යක් බෙර වාදකයා තනිවම නැට්ටුවාට සහාය වන්නේ කෙසේද?", "යක් බෙරයේ හඬින්ම ලය හා තාලය පැහැදිලිව නාද කිරීමෙන්", "ප්‍රේක්ෂකයන්ට අත්පුඩි ගසන්නට කීමෙන්", "බෙරය පසෙකින් තබා නැටීමෙන්", "සීනුවක් නාද කිරීමෙන්", "යක් බෙරයේ තියුණු නාදය නැට්ටුවාට තාලය පැහැදිලිව ග්‍රහණය කරගැනීමට උපකාරී වේ."),
        q("පහතරට වෙස්මුහුණු කලාවේ 'මහා කෝල සන්නි' මුහුණේ මැද ඇති ප්‍රධාන රූපය කුමක්ද?", "මහ කෝල සන්නි යකාගේ රෞද්‍ර මුහුණ", "මොනර රූපයක්", "හංස රූපයක්", "නෙළුම් මලක්", "මැද විශාල යක් මුහුණත් දෙපස අනෙක් සන්නි මුහුණු 18 ත් කැටයම් කර ඇත."),
        q("පහතරට නර්තනයේ 'කෙණ්ඩි පාලිය' ඉදිරිපත් කිරීමේදී යොදාගන්නා ප්‍රධාන පූජා භාණ්ඩය කුමක්ද?", "පිරිසිදු ජලය හෝ පැන් පිරවූ කෙණ්ඩිය", "මැටි පහනක්", "කඩුවක්", "ගල් ගෙඩියක්", "ශුද්ධ පැන් ඉසීමෙන් මඩුව හා ආතුරයා පිරිසිදු කිරීම කෙණ්ඩි පාලියේ අරමුණයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'නාග රක්ෂ' නැටුමේදී නැට්ටුවා පෙන්නුම් කරන ප්‍රධාන චලන ස්වභාවය කුමක්ද?", "වේගවත් කැරකිලි හා නාගයා මෙන් පෙනය පුප්පන සෘජු ඉරියව්", "බිම වැතිරී නිදා ගැනීම", "සෙමින් ඉදිරියට බඩගෑම", "අත් නොසොල්වා ඇවිදීම", "නාග රක්ෂ වෙස්මුහුණ පැළඳ අලංකාරව රඟ දක්වන ජනප්‍රිය නර්තන අංගයකි."),
        q("පහතරට 'රට යකුම' ශාන්තිකර්මයේදී රඟ දක්වන 'දරු නැළවිල්ල' අංගයෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "ගැබිනි මවගේ සිත සැනසීම හා නිරෝගී දරු උපතකට ආශිර්වාද කිරීම", "රැස්ව සිටින පිරිස නිදි කරවීම", "බෙර වාදනය නතර කිරීම", "කෝලම් රජු පිළිගැනීම", "දරු පැටවෙකු නළවන අයුරු අභිනයෙන් දක්වමින් මවට මානසික සහනය ලබා දේ."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'අංග ලක්ෂණ' අතිශයෝක්තියෙන් කැටයම් කරන්නේ ඇයි?", "පන්දම් එළියේ දුර සිට භාවය පැහැදිලිව පෙනීමට", "වෙල් කදුරු ලී කොටය අපතේ යාම වළක්වා ගැනීමට", "සාදිලිංගම් තීන්ත ප්‍රමාණය ඉතිරි කර ගැනීමට", "මුහුණේ බර අඩු කර නැටුම වේගවත් කිරීමට", "විශාල ඇස්, නාසය හා දත් රාත්‍රී ආලෝකයේදී පැහැදිලිව දිස්වේ."),
        q("පහතරට නැටුමේදී 'පහතරට අත් චලන' උඩරට අත් චලනවලින් වෙනස් වන ප්‍රධාන ආකාරය කුමක්ද?", "උරහිස් මට්ටමින් හා පහළින් පළල්ව හා ජවසම්පන්නව දෑත් විහිදුවීම", "කිසිසේත්ම දෑත් ඉහළ නොදැමීම", "අත් දෙක බැඳ තැබීම", "ඇඟිලි සියල්ල මිට මොළවා සිටීම", "පහතරට නැටුමේ බර ගතිය හා ශක්තිය එහි අත් චලනවලින් පෙනේ."),
        q("පහතරට 'දහඅට සන්නියේදී' එන 'පිස්සු' හා 'බිහිරි' වැනි සන්නි චරිත මගින් රෝගියාට ලැබෙන මානසික ප්‍රතිලාභය කුමක්ද?", "හාස්‍යය තුළින් රෝග බිය දුරු වී සිත සැහැල්ලු වීම", "රෝගියා තුළ පවතින භීතිය තවත් වර්ධනය වීම", "යාග මඩුවෙන් පිටතට බියෙන් පලා යාම", "රාත්‍රී යාගය අතරතුර නින්ද නොයා සිටීම", "සන්නි චරිතවල විනෝදාත්මක දෙබස් රෝගියාගේ සිත සතුටු කරන මනෝ චිකිත්සාවකි."),
        q("පහතරට නර්තන ක්ෂේත්‍රයේදී 'පූනා මඩුව' යනු කුමන ආකාරයේ ශාන්තිකර්මයක්ද?", "ගව සම්පතේ හා ගොවිතැනේ ආරක්ෂාව පතා කරන පහතරට යාගයකි", "විවාහ මංගල්‍යයකි", "වන්නම් අරංගැටුමකි", "නව නිවසකට ගෙවැදීමකි", "වැවිලි හා ගව සම්පතට වැළඳෙන දෝෂ දුරු කර ගැනීමට පූනා මඩුව පැවැත්වේ."),
        q("පහතරට 'සන්නි' යකුන් වේදිකාවට පැමිණීමට පෙර රඟ දක්වන 'දොළොස් පාලිය' අවසානයේ පැමිණෙන විශේෂ පාලිය කුමක්ද?", "පන්දම්, කළස් හා සළු යන පාලි නැටුම් පෙළ", "උඩරට දහඅට වන්නම් පූජා පෙළ", "ගැමි කළගෙඩි හා කුලු නැටුම් පෙළ", "සිංහල අවුරුදු රබන් පද පෙළ", "පිරිසිදු කිරීම් හා ආශිර්වාද ගෙනෙන පාලි කොටස් වලින් පසුව සන්නි යකුන් පැමිණේ."),
        q("පහතරට කෝලම් නාට්‍යයේදී 'කපිරි කෝලම' හෝ 'හේවා කෝලම' තුළින් පෙන්වන ඓතිහාසික සාධකය කුමක්ද?", "විදේශීය ආක්‍රමණික හමුදා හා වෙනස් සංස්කෘතික බලපෑම්", "අනුරාධපුර වැව් තැනීම", "පොළොන්නරු ගල් විහාරය", "සීගිරි චිත්‍ර", "යටත් විජිත සමයේ දුටු විදේශීය හේවායන් කෝලම් මුහුණු ලෙස කැටයම් විය."),
        q("පහතරට නැටුමේදී 'තෙල්මේ' නැට්ටුවා හිසේ පළඳින රතු තොප්පියට ඉහළින් සවි කරන ආභරණය කුමක්ද?", "සුදු මල් හෝ රන් පැහැ කොතක් වැනි මුදුන් කොටස", "වෙල් කදුරු ලීයෙන් කැපූ කෝලම් නාග පෙන කොටස", "උඩරට වෙස් ඇඳුමේ හිස මුදුනේ ඇති රිදී සිළුමිණ", "ගොයම් නැටුමේදී හිස මත තබන වියළි පිදුරු මිටිය", "තෙල්මේ තොප්පියේ හැඩය හා උස එම පූජා අංගයට විශේෂ පෙනුමක් ලබා දෙයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'වට්ටම්' නැටීමේදී ශිල්පියා පෙන්නුම් කරන විශේෂිත කැරකිල්ල කුමක්ද?", "වටයක් පුරා මණ්ඩි ඉරියව්වෙන් සමබරව කැරකී නැවතීම", "බිම වැතිරී පෙරළීම", "දෙපා ඔසවා හිඳගැනීම", "වේදිකාවෙන් පිටතට දිවීම", "වට්ටම් කැරකිලි පහතරට නැටුමේ ප්‍රබල රිද්මමය ශක්තිය විදහා දක්වයි."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'වෙල් කදුරු' ලීය තෝරා ගැනීමට බලපෑ අනෙක් වැදගත් හේතුව කුමක්ද?", "සිනිඳු තන්තු පිහිටීම නිසා පිහි හා නියන්වලින් සියුම් කැටයම් කැපිය හැකි වීම", "එම ලීය කිසිදු ආයුධයකින් කැපිය නොහැකි තරම් තද ගලක් මෙන් වීම", "එම ලීය වතුර මතුපිට පාවී නොයා ජලයේ ගිලෙන තරම් අධික බරකින් යුක්ත වීම", "සායම් ගැල්වීමකින් තොරවම ලීය කපන විට ඉබේම තද නිල් පැහැ ගැන්වීම", "සැහැල්ලු බව මෙන්ම සියුම් කැටයම් කිරීමේ පහසුව කලාකරුවාට ඉතා වැදගත් වේ."),
        q("පහතරට නැටුම් ක්ෂේත්‍රයේ 'ගිනි සිසිල' හෙවත් 'ගිනි පෑගීම' සිදු කරන නැට්ටුවන් ඊට පෙර රැකිය යුතු විනය කුමක්ද?", "නිර්මාංශව සිටීම, පිරිසිදු වීම හා පූජනීය පේවීම", "බර ආහාර අනුභව කිරීම", "පාවහන් පැළඳ සිටීම", "මත්පැන් පානය කිරීම", "ශාන්තිකර්ම චාරිත්‍ර අනුව පේවී පිරිසිදු සිතින් ගිනි මැලය තරණය කිරීම අනිවාර්ය වේ."),
        q("පහතරට 'දහඅට සන්නිය' අතුරින් 'දෙමළ සන්නිය' වේදිකාවට පැමිණි විට යොදාගන්නා විශේෂ නාට්‍ය උපක්‍රමය කුමක්ද?", "වෙනත් භාෂා වචන මිශ්‍ර කර හාස්‍යජනක සංවාද පැවැත්වීම", "සම්පූර්ණයෙන් නිහඬව සිටීම", "උඩරට වන්නම් ගැයීම", "බැලේ නැටීම", "විවිධ සංස්කෘතික ලක්ෂණ හාස්‍යයට නඟමින් ප්‍රේක්ෂකයා පිනවීම මෙහිදී සිදු වේ."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'මාතර' සහ 'බෙන්තර' ගුරුකුල දෙක අතර වෙනසක් හඳුනාගත හැක්කේ කුමන අංගයකින්ද?", "යක් බෙර පද ගැයෙන රටා, සන්නි පෙළපාලි අනුපිළිවෙළ සහ කවි තාලවලින්", "එක් අයෙකු ගිටාර් වැයීමෙන්", "එක් අයෙකු උඩරට වෙස් තට්ටු පැළඳීමෙන්", "කිසිදු බෙරයක් භාවිත නොකිරීමෙන්", "ගුරු පරම්පරා අනුව යාග චාරිත්‍ර හා තාල වාදනවල සියුම් වෙනස්කම් පවතී."),
        q("පහතරට වෙස්මුහුණු සංරක්ෂණය කිරීම සඳහා අම්බලන්ගොඩ පිහිටුවා ඇති ප්‍රධාන මධ්‍යස්ථානය කුමක්ද?", "අම්බලන්ගොඩ වෙස්මුහුණු කෞතුකාගාරය", "මහනුවර වෙස් ආභරණ කෞතුකාගාරය", "කොළඹ සම්භාව්‍ය සංගීත කෞතුකාගාරය", "රත්නපුර සබරගමු බෙර කෞතුකාගාරය", "පැරණි කෝලම් හා සන්නි මුහුණු පිළිබඳ දත්ත හා ආකෘති මෙහි සංරක්ෂණය කර ඇත."),
        q("පහතරට නැටුමේදී 'තෙල්මේ' නැට්ටුවන් අතැතිව හිස මත තබාගෙන හෝ අල්ලාගෙන නටන 'තෙල්මේ කළය' නැටුමේ සංකේතය කුමක්ද?", "දේව ආශිර්වාදය හා සශ්‍රීකත්වය", "ජල දූෂණය", "රෝග බෝ කිරීම", "නියඟය", "ශාන්තිකර්ම මඩුවේදී ආශිර්වාද ගෙනෙන චාරිත්‍ර නැටුමක් ලෙස මෙය පිළිගැනේ."),
        q("පහතරට නර්තනයේදී 'සළු පාලිය' ඉදිරිපත් කරන ශිල්පියා බොහෝ විට සැරසී සිටින්නේ කුමන වර්ණ ඇඳුමකින්ද?", "සුදු පැහැති සළු හා රතු ඉණ පටියකින්", "සම්පූර්ණ කළු ඇඳුමකින්", "කොළ පැහැති නිල ඇඳුමකින්", "ප්ලාස්ටික් වැහි කබායකින්", "සුදු පැහැය පවිත්‍රතාව හා පත්තිනි මෑණියන්ගේ ගෞරවය සංකේතවත් කරයි."),
        q("පහතරට කෝලම් නාට්‍යයේදී රජු හා බිසව වේදිකාවට පැමිණීමට පෙර 'අණ බෙරකරු' පැමිණ කරන්නේ කුමක්ද?", "රජුගේ පැමිණීම දන්වා හාස්‍යජනක විස්තර කීම", "කෝලම් රංගනය අවසන් වූ බව සභාවට දැන්වීම", "වෙස්මුහුණු සියල්ල වේදිකාවෙන් ඉවත් කිරීම", "යක් බෙර වාදනය සම්පූර්ණයෙන් නතර කිරීම", "කෝලම් කතා පෙළ ක්‍රමවත්ව ගොඩනැඟීමට අණබෙර කෝලම මුල් වේ."),
        q("පහතරට 'මඩු පුරය' හෙවත් 'ගම්මඩුව' පැවැත්වීමේදී ගමේ සියලු දෙනා එක්ව දායක වන්නේ ඇයි?", "මුළු ගමටම පොදුවේ ආරක්ෂාව, වැසි හා සශ්‍රීකත්වය ලබා ගැනීමට", "එක් පුද්ගලයෙකුට පමණක් තෑගි දීමට", "නවකයන් බිය ගැන්වීමට", "ගමෙන් පිටව යාමට", "සාමූහික ආගමික හා සංස්කෘතික එකමුතුව ගම්මඩුව මගින් තහවුරු වේ."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'වෙස්මුහුණු' නැතිව ඉදිරිපත් කරන ප්‍රධාන සමූහ නර්තන අංගය කුමක්ද?", "තෙල්මේ නැටුම", "දහඅට සන්නි නැටුම", "ජසයා හා ලෙන්චිනා කෝලම", "මහ කෝල සන්නිය", "තෙල්මේ නැටුමේදී වෙස්මුහුණු නොපළඳින අතර තෙල්මේ තොප්පිය පළඳී."),
        q("පහතරට වෙස්මුහුණු කැපීමේදී 'නියන්' (Chisels) විවිධ ප්‍රමාණවලින් භාවිත කරන්නේ ඇයි?", "රළු කොටස් හාරා සියුම් කැටයම් මතු කිරීමට", "දැව කොටය දුම් මැස්සේ තබා වියළා ගැනීමට", "ස්වාභාවික තීන්ත හා දොරණ තෙල් මිශ්‍ර කිරීමට", "යක් බෙරයේ දෙපස ගව සම් කපා සවි කිරීමට", "හැඩගැන්වීම සඳහා පළල් නියන්ද සියුම් වැඩ සඳහා පටු නියන්ද භාවිත වේ."),
        q("පහතරට නර්තනයේ 'ගිනි පෑගීම' හැරුණු විට අග්නි හෙවත් ගින්න සම්බන්ධ අනෙක් ප්‍රධාන පාලිය කුමක්ද?", "පන්දම් පාලිය", "කෙණ්ඩි පාලිය", "සළු පාලිය", "කළස් පාලිය", "දැල්වෙන පන්දම් හසුරුවමින් දුම්මල ගසා ආශිර්වාද කිරීම පන්දම් පාලියයි."),
        q("පහතරට නර්තන ක්ෂේත්‍රයේදී 'පහතරට යක් බෙරය' සාමාන්‍යයෙන් දිගින් කෙතරම් වේද?", "අඩි දෙකහමාරක් පමණ දිග සිලින්ඩරාකාර බෙරයකි", "අඟල් පහක් පමණ කුඩා බෙරයකි", "අඩි දහයක් දිග බෙරයකි", "පන්තේරුවක් මෙන් පැතලි බෙරයකි", "සෘජු නලයක් වැනි හැඩයක් ගන්නා යක් බෙරය දිගින් අඟල් 27-30 පමණ වේ."),
        q("පහතරට 'දහඅට සන්නිය' රඟ දක්වන විට සන්නි යකුන් වේදිකාවට කැඳවීම සඳහා පිහිටුවන තිරය හඳුන්වන්නේ කුමන නමකින්ද?", "කඩතුරාව හෙවත් යක් තිරය", "මල් යහන", "කණු තොරණ", "පහන් පැල", "වෙස්මුහුණු පැළඳ සිටින ශිල්පියා කඩතුරාව පිටුපස සිට එක්වරම ඉදිරියට පැමිණේ."),
        q("පහතරට 'කෝලම්' කලාවේදී 'සිංහ කෝලම' හෝ 'ව්‍යාඝ්‍ර කෝලම' මගින් නිරූපණය කරන්නේ කුමක්ද?", "වන සතුන්ගේ රෞද්‍ර බව හා අලංකාර චලන රටා", "මහලු ගොවියන්ගේ ජීවිතය", "පාසල් ශිෂ්‍යයන්ගේ හැසිරීම", "රාජ සභා නීති", "වන සතුන්ගේ හැසිරීම වෙස්මුහුණු සහ චලන මගින් කෝලම් තුළ රඟ දැක්වේ."),
        q("පහතරට නැටුමේදී ශිල්පියෙකු තම ගුරු පරම්පරාවේ ආශිර්වාදය ලබා උත්සවශ්‍රීයෙන් පළඳින හිස් ආභරණය කුමක්ද?", "පහිම්පත හෝ පහතරට හිස් පළඳනාව", "උඩරට වෙස් තට්ටුව", "අරාබි තලප්පාව", "ලෝහ හෙල්මටය", "පුහුණුව අවසන් කළ පසු පහතරට ශිල්පීන්ට හිසේ පටි හෙවත් පහිම්පත් බැඳීම සිදු කෙරේ."),
        q("පහතරට 'මහ සන්නි' නැටුම අවසානයේදී මහ කෝල සන්නි යකා රෝගියාට දෙන පොරොන්දුව කුමක්ද?", "පිදේනි භාරගෙන රෝගියාගේ සියලු රෝගාබාධ සුව කර ආපසු යන බව", "තවදුරටත් නිවසේ රැඳී සිටින බව", "බෙර වාදකයා සමඟ සටන් කරන බව", "තොරණ කඩා දමන බව", "ආතුරයාගේ රෝග බිය සම්පූර්ණයෙන් දුරු වූ බවට මානසික සහතිකයක් මෙයින් ලැබේ."),
        q("පහතරට 'සන්නි' යකුන් අතුරින් 'කුරුම්බර' හෝ 'මරු' සන්නි මුහුණුවලින් ප්‍රකාශ වන භාවය කුමක්ද?", "රෞද්‍ර, භයානක හා වේගවත් රෝග කිපීම", "ශාන්ත සිනහව", "ළමා සුරතල් බව", "විහිළු කතාව", "භයංකර බව උපරිමයෙන් පෙන්වන වෙස්මුහුණු සන්නි අතර දැකිය හැකිය."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'නාග කන්‍යා' මුහුණ අලංකාර වන්නේ කුමන කැටයමකින්ද?", "මුහුණ දෙපස හා හිස මත නාග පෙන සහ මල් කැටයම්වලින්", "දිගු අං යුගලයකින්", "සිංහ දත්වලින්", "රැවුලකින්", "ලාලිත්‍යමය හා සුන්දර ස්ත්‍රී මුහුණක නාග ලක්ෂණ එක් කර ඇත."),
        q("පහතරට 'ගිනි පෑගීම' සඳහා සූදානම් කරන ගිනි මැලයේ දර ලෙස බොහෝ විට යොදාගන්නා දැව වර්ගය කුමක්ද?", "සියඹලා හෝ කොස් වැනි අඟුරු හොඳින් රැඳෙන දැව", "වියළි තණකොළ පමණි", "කඩදාසි පෙට්ටි", "ප්ලාස්ටික් කැබලි", "දීප්තිමත් රතු අඟුරු තට්ටුවක් සෑදෙන ලෙස හොඳ දර වර්ග තෝරා ගනී."),
        q("පහතරට කෝලම් නැටුමේ 'පන්දම් අල්ලන්නා' වෙස්මුහුණු චරිතයට ආලෝකය සපයන්නේ කෙසේද?", "වෙස්මුහුණ ඉදිරියෙන් කොප්පරා පන්දම් අල්ලා ගැනීමෙන්", "වේදිකාව ඉහළින් විදුලි පන්දම් දැල්වීමෙන්", "රන් පැහැ කැඩපතකින් ආලෝකය යොමු කිරීමෙන්", "ගිනි පෙට්ටියක කුඩා ගිනි කූරු දැල්වීමෙන්", "පන්දම් එළිය වැටීමෙන් වෙස්මුහුණේ කැටයම් ජීවමාන සෙවණැලි මවයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'වට්ටම්' නැටීමේදී ශිල්පියා පෙන්නුම් කරන 'අත් ගැසීම්' හෙවත් මුද්‍රා රටාව කෙබඳුද?", "පුළුල්ව ඉදිරියට හා පැත්තට දෑත් විහිදුවමින් තාලයට පද ඇල්ලීම", "අත් දෙක සාක්කුවේ දමා ගැනීම", "හිස පිටුපසින් අත් බැඳීම", "ඇඟිලි සෙලවීමෙන් වැළකීම", "වට්ටම් පදවල ජවය දෑත්වල ශක්තිමත් හැසිරවීමෙන් පෙනේ."),
        q("පහතරට 'යක් බෙරය' නිමවීමේදී බෙරයේ දෙපස විෂ්කම්භය කෙබඳු හැඩයක් ගනීද?", "වම් ඇස හා දකුණු ඇස දෙකම සමාන ප්‍රමාණයකින් යුක්ත සිලින්ඩරාකාර හැඩයක්", "එක් කෙළවරක් ඉතා පළල් වී අනෙක් කෙළවර ඉතා පටු වේ", "පැතලි රවුමකි", "සතරැස් පෙට්ටියකි", "උඩරට ගැටබෙරයේ මැද මහත් වුවත් පහතරට යක් බෙරය සෘජු සිලින්ඩරයකි."),
        q("පහතරට 'රට යකුමේදී' නිරූපණය කරන 'මුතු කුඩ පාලිය' මගින් දැක්වෙන්නේ කුමක්ද?", "බුදුරදුන්ට හා දෙවියන්ට සේසත් හා කුඩ පූජා කිරීම", "වර්ෂාවෙන් ආරක්ෂා වී වේදිකාව වියළිව තැබීම", "මධ්‍යාහ්න හිරු රශ්මියෙන් නැට්ටුවන් රැකගැනීම", "කෝලම් රජු වේදිකාවෙන් ඉවතට පලවා හැරීම", "බුදුරදුන්ට හා මහා බ්‍රහ්මයාට පූජා කළ චාරිත්‍ර රංගයට නඟා ඇත."),
        q("පහතරට 'කෝලම්' කලාවේදී 'නාග කෝලම' හා 'සන්නි' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "කෝලම ගැමි නාට්‍ය රංගනයක් වන අතර සන්නිය රෝග සුව කරන ශාන්තිකර්මයකි", "දෙකම එකම උඩරට කංකාරියට අයත්ය", "කෝලම්වල වෙස්මුහුණු නැත", "සන්නි යනු දිවා කාලයේ ක්‍රීඩාවකි", "අරමුණ හා රංග ස්වභාවය අනුව මෙම කලා අංග දෙක පැහැදිලිව වෙන් වේ."),
        q("පහතරට 'දහඅට සන්නියේදී' ආතුරයා ඉදිරියේ 'පන්දම් පූජාව' පවත්වන යකැදුරා කටයුතු කරන්නේ කුමන චාරිත්‍රයකට අනුවද?", "මන්ත්‍ර හා කවි ගයමින් දුම්මල ගසා දෝෂ දුරු කිරීම", "කිසිවක් නොකියා බලා සිටීම", "පන්දම් නිවා දැමීම", "බෙර වාදනය තහනම් කිරීම", "දුම්මල ගිනි දැල් මැද රෝගියාට මානසික ප්‍රබෝධයක් ලැබේ."),
        q("පහතරට නැටුමේ 'පහතරට මූලික පාද චලන' පුහුණුවීමේදී වැඩි අවධානයක් දෙන ශරීර කොටස කුමක්ද?", "දණහිස් නවා තැබීම, වළලුකර පාලනය සහ ඉණ පැද්දීම", "ඇඟිලි තුඩුවලින් සිට ගැනීම පමණක්", "කොන්ද පසුපසට නැමීම", "බෙල්ල ගල් ගැස්වීම", "පහතරට නැටුමේ බර ගතිය හා රිද්මය මණ්ඩි ස්ථාවරත්වයෙන් උපදී."),
        q("පහතරට 'සූනියම් කැපිල්ල' යාගයේදී ඉදිකරන 'සූනියම් වීදියේ' ඇති විශේෂිත කුටි සංඛ්‍යාව හෝ සැකැස්ම කුමක්ද?", "සත් මහල් හෝ අට මහල් ගොක් කොළ වීදියකි", "සාමාන්‍ය කුඩා ලී මේසයකි හා පුටුවකි", "සිමෙන්ති බැමි බැඳි ගඩොල් තාප්පයකි", "තිර රෙදිවලින් වැසූ කුඩා කාමරයකි", "මහ සම්මත රජුගේ කතා පුවත සමඟ සූනියම් වීදිය ඉතා කලාත්මකව ගොඩනඟයි."),
        q("පහතරට 'සන්නි' වෙස්මුහුණුවල 'මුඛය' බොහෝ විට ඇද වූ හෝ විකෘති හැඩයකින් කපන්නේ ඇයි?", "අදාළ රෝගයේ බාහිර ශාරීරික විකෘතිය නිරූපණය කිරීමට", "කලාකරුවාට කැපීමට අමතක වූ නිසා", "ලීය ඇද වූ නිසා", "බර අඩු කිරීමට", "වාත රෝග, ගොළු බව හා අංශභාග රෝග ලක්ෂණ මුහුණින් පෙන්වයි."),
        q("පහතරට 'ගුරුළු රක්ෂ' වෙස්මුහුණේ මුහුණ මැද නාගයෙකු සිටිනු දැකිය හැක්කේ කොතැනද?", "ගුරුළාගේ හොටින් ඩැහැගත් හෝ ගෙල වටා එතුණු ආකාරයෙන්", "ගුරුළාගේ කකුල් යට", "හිස පිටුපස", "බෙරය මත", "ගුරුළා නාගයන්ගේ සතුරා වන බව පුරාවෘත්තයෙන් පෙන්වයි."),
        q("පහතරට 'කෝලම්' නාට්‍යයේ 'කාරියකරවන රාළ' නමැති චරිතය හඳුන්වන වෙනත් සුලබ නාමය කුමක්ද?", "සභාපති", "වැදි රජු", "මහ සොහොන් යකා", "පත්තිනි කපු මහතා", "මුළු කෝලම් රංගනයම මෙහෙයවන්නේ සභාපති හෙවත් කාරියකරවන රාළය."),
        q("පහතරට නැටුමේදී 'පහතරට උඩැක්කි' වෙනුවට ප්‍රධාන ලෙස භාවිත කරන අනෙක් වාද්‍ය භාණ්ඩය කුමක්ද?", "තම්මැට්ටම සහ හොරණෑව (දේව යාගවලදී)", "සිතාරය", "තබ්ලාව", "මෘදංගය", "යක් බෙරයට අමතරව ගම්මඩු පෙරහැරවලදී හේවිසි භාණ්ඩද වැයේ."),
        q("පහතරට 'තෙල්මේ' නැටුමේදී නැට්ටුවන් අඳින 'සුදු රැළි හඟල' රෙද්ද ඉණ වටේට සකස් කරන්නේ කෙසේද?", "ඉදිරියෙන් හා දෙපසින් රැළි තබා ඉණ පටියෙන් බැඳ", "දිගු කලිසමක් ආකාරයෙන් පාද වටා මසා", "උරහිස් හරහා සළුවක් සේ කරේ ඔතා", "සුදු තලප්පාවක් මෙන් හිස වටා බැඳ", "කැරකෙන විට මලක් මෙන් විහිදෙන සේ හඟල රැළි තබා අඳියි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'මල් යහන්' පූජාව අවසානයේ පිදේනි තටු ගෙන යන යකැදුරා සිදු කරන්නේ කුමක්ද?", "නියමිත දිශාවට මුහුණ ලා යකුන් පිටත් කර ආතුරයාට ආශිර්වාද කිරීම", "තටුව වේදිකාව මැද තබා නිදා ගැනීම", "තටුව කඩා දැමීම", "බෙරය විසි කිරීම", "දිසා පූජාවෙන් පසු යාගයේ මානසික සුවය සම්පූර්ණ වේ."),
        q("පහතරට වෙස්මුහුණු කලාවේ 'මූර්ති හා චිත්‍ර' ශිල්පය අධ්‍යයනය කිරීමෙන් ශිෂ්‍යයාට ලැබෙන ප්‍රධාන ප්‍රතිලාභය කුමක්ද?", "සාම්ප්‍රදායික කැටයම් හා වර්ණ රටා පිළිබඳ නිර්මාණශීලී අවබෝධය", "පෙරදිග හස්ත මුද්‍රා ශ්ලෝක හා බෙර තාල කටපාඩම් වීම", "විදේශීය බැලේ නර්තන සපත්තු මැසීමේ හැකියාව ලැබීම", "වේදිකා පසුබිම් ආලෝක පද්ධති සැකසීමේ පුහුණුව ලැබීම", "දේශීය වෙස්මුහුණු චිත්‍ර කලාව සෞන්දර්ය අධ්‍යාපනයේ වටිනා අංගයකි."),
        q("පහතරට 'සන්නි' යාගයේ 'මුරුත සන්නිය' හෝ 'මරු සන්නිය' පැමිණි විට යොදාගන්නා ආලෝක උපක්‍රමය කුමක්ද?", "පන්දම් එළිය අඩු කර දුම්මල ගසා භීතිය මැවීම", "මධ්‍යාහ්න හිරු එළිය යට ශාන්තිකර්මය පැවැත්වීම", "වේදිකාවේ පිටුපසින් ප්‍රොජෙක්ටර් තිර දැමීම", "මඩුවේ සියලු පහන් හා පන්දම් නිවා දැමීම", "මනෝභාවයන් ඉස්මතු කිරීමට ආලෝකය හා දුම ස්වාභාවිකව පාලනය කෙරේ."),
        q("පහතරට 'කෝලම්' කලාවේදී 'සිංහබාහු' හෝ 'මනමේ' වැනි දිගු කතාන්දර රඟ දක්වන විට එය හඳුන්වන්නේ කුමන කෝලම් අංගය ලෙසද?", "සඳකිඳුරු හෝ ගෝඨයිම්බර වැනි කතා කෝලම්", "දහඅට සන්නියේ රෝග නිවාරණ යාග අංගය", "සූනියම් කැපිල්ලේ වඩිග පටුන රංගනය", "උඩරට ගැමි කමතේ රඟ දක්වන සොකරි නාටකය", "පෙළපාලිවලින් පසුව පහතරට කෝලම් රාත්‍රියේදී සම්පූර්ණ කතා වස්තුවක් රඟ දැක්වේ."),
        q("පහතරට 'ගෝඨයිම්බර කෝලම' රඟ දැක්වෙන විට ප්‍රධාන වශයෙන්ම නිරූපණය කෙරෙන චරිතය කවුද?", "ගෝඨයිම්බර හා ජයසේන යක්ෂයාගේ පුවත", "විජය කුමරු හා කුවේණියගේ පුවත", "මනමේ කුමරු හා වැදි රජුගේ පුවත", "මලය රජු හා පඬුවස්දෙව් රජුගේ පුවත", "ජනප්‍රිය සිංහල වීර කථා පවා කෝලම් රංගනයට විෂය වී ඇත."),
        q("පහතරට 'දහඅට සන්නියේදී' සන්නි යකුන්ට නියමිත අනුපිළිවෙළක් පවතීද?", "ඔව්, ගුරුකුලය අනුව ආරම්භක සන්නි සිට පිළිවෙළක් ඇත", "නැත, හිතුමතේ පැමිණේ", "එක් සන්නියක් පමණක් දහඅට වරක් එයි", "සන්නි කිසිවෙක් නොඑයි", "විධිමත් යාග ව්‍යුහය තුළ පැමිණෙන අනුපිළිවෙළ සම්ප්‍රදායිකව සුරැකේ."),
        q("පහතරට නැටුමේදී 'තෙල්මේ' නැටුමට අදාළව ගැයෙන ප්‍රධාන කවි වර්ගය කුමක්ද?", "තෙල්මේ උපත හා දෙවියන් පුදන කවි", "කුඹුරේ ගොයම් කැපීමේ ජන කවි", "මිනිරන් පතල්වල ගයන පතල් කවි", "ගඟේ පාරු පැදීමේ පාරු කවි", "පූජා නැටුමේ පසුබිම් කතාව හා දේව ගුණ තෙල්මේ කවිවලින් ගැයේ."),
        q("පහතරට 'පාලි' අංග අතරින් 'කෙණ්ඩි පාලිය' ඉදිරිපත් කිරීමේදී නැට්ටුවා අත තබාගෙන සිටින කෙණ්ඩියේ පිරී ඇත්තේ කුමක්ද?", "කහ දිය හෙවත් ශුද්ධ පැන්", "පොල් තෙල්", "වැලි", "සීනි", "රෝග හා අපවිත්‍රතා දුරු කරන ඖෂධීය පිරිසිදු ජලය මෙහි තබා ගනී."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'රන්වන් හා කහ පැහැය' වැඩි වශයෙන් යොදාගනු ලබන්නේ කුමන චරිත මුහුණුවලටද?", "දේව චරිත, රාජකීය චරිත හා උතුම් බලවේගවලට", "යක්ෂ චරිතවලට පමණි", "රෝගී සන්නිවලට පමණි", "හේවා සෙබළුන්ට", "සෞම්‍ය, ශ්‍රේෂ්ඨ හා රාජකීය ගුණ පෙන්වීමට කහ හා රන් පැහැය යොදයි."),
        q("පහතරට 'මහ සොහොන් සමයමේදී' යකැදුරා 'සොහොන් පිටිය' සංකේතවත් කිරීමට මඩුව තුළ සකසන්නේ කුමක්ද?", "සොහොන් තටුව හා බිම් අතුරුව", "ගල් කුළුණක්", "පිහිනුම් තටාකයක්", "වේදිකා පියානෝවක්", "රෝගියාගේ සිතේ පවතින මරණ බිය පරාජය කිරීමට මෙම සංකේතාත්මක සැකැස්ම යොදයි."),
        q("පහතරට 'සූනියම් කැපිල්ලේදී' භාවිත කරන 'පුහුල්' ගෙඩිය වටා අඳිනු ලබන සංකේත මොනවාද?", "සත් තිත් හෝ මන්ත්‍ර රේඛා සටහන්", "වර්ණවත් මල්", "අංක වගු", "සිතියම්", "පූජනීය බලයෙන් වින දෝෂ හිර කිරීමේ සංකේත ලෙස එසේ කරයි."),
        q("පහතරට නර්තන ශිල්පියෙකු 'වේදිකා රංගනයක්' සඳහා සූදානම් වීමේදී තම 'තෙල්මේ තොප්පිය' හිසේ රඳවා ගන්නේ කෙසේද?", "හිස වටා තදින් බඳින ලද පටියකින් හා යටින් බැඳි රැහැනකින්", "මැලියම් ආලේප කිරීමෙන්", "ඇණ ගැසීමෙන්", "වම් අතින් අල්ලාගෙන සිටීමෙන්", "වේගවත් කැරකිලිවලදී හිස්වැසුම නොවැටී රැකීමට ආරක්ෂිතව බඳිනු ලැබේ."),
        q("පහතරට නර්තන ක්ෂේත්‍රයේ 'ගුරු ශිෂ්‍ය' සම්ප්‍රදාය තුළ පවතින උසස් සිරිතක් වන්නේ කුමක්ද?", "බෙරය හා හිස් පැළඳුම බිම නොදමා ගෞරවයෙන් වැඳ අතට ගැනීම", "භාණ්ඩ පයින් තල්ලු කිරීම", "ගුරුවරයාට පසුපස හැරී සිටීම", "නිහඬව පිටව යාම", "වාද්‍ය භාණ්ඩ හා රංග වස්ත්‍ර පූජනීය වස්තු ලෙස සැලකීම කලා විනයයි."),
        q("පහතරට 'දෙවොල් මඩුවේදී' 'ගිනි පෑගීම' සිදු වන අවස්ථාවේදී ප්‍රේක්ෂක පිරිස කරන්නේ කුමක්ද?", "සාධුකාර දෙමින් භක්තියෙන් ආශිර්වාද පැතීම", "ගිනි මැලය නිවීම සඳහා වතුර ඉසීම", "යක් බෙර වාදකයාට බාධා කරමින් කෑගැසීම", "වේදිකාව මැදට දිව ගොස් නැටීම", "මුළු ගමේම සාමූහික භක්තිය එම මොහොතේදී එක්වේ."),
        q("පහතරට 'කෝලම්' කලාවේදී 'මුහුණු කැපීම' අද වන විට ලංකාවේ කුමන කර්මාන්තයකට විශාල දායකත්වයක් සපයයිද?", "සංචාරක හා සංස්කෘතික අත්කම් කර්මාන්තයට", "ලෝහ කඩු හා සන්නාහ නිෂ්පාදන කර්මාන්තයට", "නවීන පාසල් නිල ඇඳුම් මැසීමේ කර්මාන්තයට", "විදේශීය බටහිර සංගීත කර්මාන්තයට", "දේශීය හා විදේශීය සංචාරකයෝ අම්බලන්ගොඩ වෙස්මුහුණු ඉතා අගය කොට මිලදී ගනිති."),
        q("පහතරට 'පාලි' අංග අතරින් 'සළු පාලියේදී' නැට්ටුවා 'සුදු සළුව' ආතුරයා ඉදිරියේ වනන්නේ ඇයි?", "සියලු අපල උපද්‍රව සළුවෙන් පිසදා ආශිර්වාද ලබා දීමට", "දූවිලි පිස දැමීමට පමණි", "ගෙවල් අතුගෑමට", "වෙස්මුහුණ වැසීමට", "පත්තිනි මෑණියන්ගේ ශුද්ධ සළුවේ බලය සංකේතවත් කිරීම සිදු කෙරේ."),
        q("පහතරට නැටුමේදී 'යක් බෙරය' වාදනය කිරීමෙන් පසු එය ගබඩා කර තබන නිවැරදි ක්‍රමය කුමක්ද?", "රෙදි කවරයක බහා තෙතමනයෙන් තොරව තැබීම", "එළිමහනේ වැස්සට හා පින්නට තබා හැරීම", "සම් පෙඟෙන සේ ජල බඳුනක ගිල්වා තැබීම", "වේදිකාවේ පොළොව මත පෙරළා තබා යාම", "බෙර හම හා දැව කඳ තෙතමනයෙන් ආරක්ෂා කිරීම නාද ගුණය රකී."),
        q("පහතරට 'දහඅට සන්නිය' අතුරින් 'පිත් සන්නිය' සහ 'වාත සන්නිය' මෙන්ම 'සෙම් සන්නිය' එක්ව නිරූපණය කරන්නේ කුමක්ද?", "ආයුර්වේදයේ එන ත්‍රිදෝෂ සංකල්පය", "බටහිර යාන්ත්‍ර විද්‍යාව", "නූතන තාරකා විද්‍යාව", "භූගෝල විද්‍යාව", "ශ්‍රී ලාංකේය ජන වෛද්‍ය විද්‍යාව හා ශාන්තිකර්ම අතර ගැඹුරු බැඳීම මෙයින් පැහැදිලි වේ."),
        q("පහතරට 'කෝලම්' කලාවේදී 'ලියන ආරච්චි' කෝලම මගින් උපහාසයට ලක් කරන්නේ කවර සමාජ පැතිකඩක්ද?", "ගමේ ලියකියවිලි හා නීති කටයුතු කරන නිලධාරියාගේ අහංකාරය", "ගොවියන්ගේ අස්වැන්න", "ධීවරයන්ගේ මාළු ඇල්ලීම", "කුඹුරු හෑම", "ජන සමාජයේ විවිධ වෘත්තීන්ගේ අඩුපාඩු විහිළුවෙන් පෙන්වා දීම කෝලමේ සිරිතයි."),
        q("පහතරට නැටුමේදී 'මණ්ඩි ගමන්' ඉදිරිපත් කරන විට ශිල්පියාගේ 'පපුව හා උරහිස්' ඉදිරියට නැමෙන මට්ටම කෙබඳුද?", "සෘජුව එහෙත් තාලයට පැද්දෙන සේ මඳක් පළල්ව තබා ගනී", "බිමටම නැමී හිස දණහිස්වල ගාවයි", "පසුපසට වැටෙන තරම් ඇල කරයි", "කිසිසේත්ම නොසොල්වා තබයි", "පහතරට ඉරියව්වල ජවය රැඳී ඇත්තේ කය හා අත් පා සමතුලිතව ක්‍රියා කිරීම මතය."),
        q("පහතරට නර්තන සම්ප්‍රදාය පාසල් සිසුන් ප්‍රායෝගිකව ඉගෙනීමේදී ඔවුන්ට ලැබෙන ප්‍රධාන සෞඛ්‍ය ප්‍රතිලාභය කුමක්ද?", "කලවා හා ඉණ පේශි ශක්තිමත් වී සමබරතාව වැඩීම", "ශරීරයේ පොදු දෘෂ්ටිය ක්‍රමයෙන් දුර්වල වීම", "කොඳු ඇට පෙළ ඉදිරියට නැමී කුදු වී යාම", "දැඩි මානසික ආතතිය හා විඩාව ඉහළ යාම", "ශක්තිමත් මණ්ඩි පුහුණුව හා රිද්මයානුකූල පියවර ශාරීරික යෝග්‍යතාව වර්ධනය කරයි."),
        q("පහතරට නර්තන සම්ප්‍රදාය හා වෙස්මුහුණු කලාව අනාගත පරපුර සඳහා රැක ගැනීමට ගත යුතු වඩාත්ම ප්‍රායෝගික පියවර කුමක්ද?", "කලාකරුවන් ඇගයීම හා පාසල් අධ්‍යාපනය ශක්තිමත් කිරීම", "පාරම්පරික වෙල් කදුරු වෙස්මුහුණු ඉවත් කිරීම", "පැරණි කෝලම් හා සන්නි කවි පොත් බැහැර කිරීම", "පහතරට යක් බෙර වාදනය සම්පූර්ණයෙන් තහනම් කිරීම", "සංස්කෘතික අධ්‍යාපනය හා කලාකරුවන්ට අතදීම තුළින් පහතරට කලාව සුරැකේ.")
    )
}
